function renderDaysOff(){$('offList').replaceChildren();for(let [date,annual]of [...(data.daysOff||[]).map(d=>[d,false]),...(data.yearlyDaysOff||[]).map(d=>[d,true])]){let row=document.createElement('div');row.className='itemRow';let label=document.createElement('span');label.textContent=annual?'Every year · '+date:new Date(date+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',year:'numeric',month:'long',day:'numeric'});label.textContent+=(data.holidayNames?.[annual?'yearly':'dates']?.[date]?' · '+data.holidayNames[annual?'yearly':'dates'][date]:'');let remove=document.createElement('button');remove.textContent='Remove';remove.onclick=()=>{mutate(()=>{if(data.holidayNames)delete data.holidayNames[annual?'yearly':'dates'][date];let key=annual?'yearlyDaysOff':'daysOff';data[key]=data[key].filter(d=>d!==date)});renderDaysOff()};row.append(label,remove);$('offList').append(row)}if(!$('offList').children.length)$('offList').textContent='No days off added.'}
$('daysOff').onclick=()=>{endBurst();$('offDate').value=selected;$('offEnd').value='';$('offYearly').checked=false;$('offError').textContent='';renderDaysOff();$('daysOffDialog').showModal()};$('closeDaysOff').onclick=()=>$('daysOffDialog').close();$('addOffDate').onclick=()=>{let from=$('offDate').value,to=$('offEnd').value||from;if(!C.isDate(from)||!C.isDate(to)||to<from||new Date(to)-new Date(from)>3660*86400000){$('offError').textContent='Choose a valid date range of up to 10 years.';return}let list=[];for(let date of C.dates(from,to))list.push($('offYearly').checked?date.slice(5):date);mutate(()=>{let key=$('offYearly').checked?'yearlyDaysOff':'daysOff';data[key]=[...new Set([...(data[key]||[]),...list])].sort()});$('offError').textContent='';renderDaysOff()};
function renderDayTemplates(){$('templateDay').textContent='Save from / apply to '+selected;$('dayTemplateList').replaceChildren();for(let [id,t]of Object.entries(data.dayTemplates||{})){let row=document.createElement('div');row.className='itemRow';let name=document.createElement('input');name.value=t.name;name.setAttribute('aria-label','Rename template '+t.name);name.onchange=()=>{let value=name.value.trim();if(!value||Object.entries(data.dayTemplates).some(([key,other])=>key!==id&&other.name.toLowerCase()===value.toLowerCase())){$('templateError').textContent='Use a unique, non-empty template name.';name.value=t.name;return}mutate(()=>data.dayTemplates[id].name=value);$('templateError').textContent='Template renamed.'};name.maxLength=80;let apply=document.createElement('button');apply.textContent='Apply';apply.onclick=()=>{try{let result;mutate(()=>{result=PlannerPlanning.applyTemplates(data,id,$('templateFrom').value,$('templateThrough').value,[...document.querySelectorAll('[name=templateWeekday]:checked')].map(e=>+e.value),uid,$('templateSkipDaysOff').checked)});$('templateError').textContent=result.added+' blocks added; '+result.skipped+' skipped (duplicate or outside displayed hours).';notify(result.added+' template blocks added across '+result.days+' days')}catch(e){$('templateError').textContent=e.message}};let remove=document.createElement('button');remove.textContent='Delete';remove.onclick=()=>{if(!confirm('Delete the template “'+t.name+'”? Calendar entries stay.'))return;mutate(()=>{delete data.dayTemplates[id]});renderDayTemplates()};let overwrite=document.createElement('button');overwrite.textContent='Replace with this day';overwrite.onclick=()=>{let replacement=C.captureDayTemplate(data,selected,data.dayTemplates[id].name);if(!replacement.blocks.length){$('templateError').textContent='Add blocks to this day first.';return}if(!confirm('Replace this template with the selected day’s schedule?'))return;mutate(()=>data.dayTemplates[id]=replacement);$('templateError').textContent='Template replaced.';renderDayTemplates()};row.append(name,apply,overwrite,remove);$('dayTemplateList').append(row)}if(!$('dayTemplateList').children.length)$('dayTemplateList').textContent='Save a day to create your first template.'}
$('dayTemplates').onclick=()=>{endBurst();$('templateFrom').value=selected;$('templateThrough').value=selected;$('templateError').textContent='';$('dayTemplateName').value='';renderDayTemplates();$('dayTemplateDialog').showModal()};$('closeDayTemplates').onclick=()=>$('dayTemplateDialog').close();$('saveDayTemplate').onclick=()=>{let name=$('dayTemplateName').value.trim();if(!name||name.length>80){$('templateError').textContent='Give the template a name (up to 80 characters).';return}let existingId=Object.keys(data.dayTemplates||{}).find(id=>data.dayTemplates[id].name.toLowerCase()===name.toLowerCase());if(existingId&&!confirm('Overwrite the existing “'+name+'” template with this day?'))return;let t=C.captureDayTemplate(data,selected,name);if(!t.blocks.length){$('templateError').textContent='Add time blocks to this day first.';return}mutate(()=>{(data.dayTemplates??={})[existingId||uid()]=t});$('templateError').textContent='Template saved.';$('dayTemplateName').value='';renderDayTemplates()};
let cleanupSelection=new Set(),cleanupPage=0,cleanupTimer,cleanupCache=null;
function cleanupIndex(){if(!cleanupCache||cleanupCache.revision!==revision){let index=C.carriedIndex(data),items=Object.values(data.backlog).sort((a,b)=>a.title.localeCompare(b.title));cleanupCache={revision,items,status:new Map(items.map(t=>[t.id,C.carriedStatus(data,t,index)]))}}return cleanupCache}
function cleanupItems(){let q=$('cleanupFilter').value.trim().toLowerCase();return cleanupIndex().items.filter(t=>(t.title+' '+t.notes).toLowerCase().includes(q))}
function updateCleanupCount(){$('cleanupStatus').textContent=cleanupSelection.size+' selected · '+Object.keys(data.backlog).length+' total';$('removeSelectedBacklog').disabled=!cleanupSelection.size;$('removeSelectedBacklog').textContent='Remove selected ('+cleanupSelection.size+')'}
function renderCleanup(){cleanupSelection=new Set([...cleanupSelection].filter(id=>data.backlog[id]));$('cleanupList').replaceChildren();let items=cleanupItems();cleanupPage=Math.min(cleanupPage,Math.max(0,Math.ceil(items.length/100)-1));for(let t of items.slice(cleanupPage*100,cleanupPage*100+100)){let row=document.createElement('label');row.className='itemRow';let check=document.createElement('input');check.type='checkbox';check.checked=cleanupSelection.has(t.id);check.onchange=()=>{if(check.checked)cleanupSelection.add(t.id);else cleanupSelection.delete(t.id);updateCleanupCount()};let label=document.createElement('span');label.textContent=t.title;let detail=document.createElement('small');let status=cleanupIndex().status.get(t.id);detail.textContent=(status.completed?'Completed · history kept':'Unfinished')+(t.originId?' · Auto-carried':'')+(status.edited?' · Edited / unverified':'')+(status.scheduled?' · Scheduled':'')+(status.source?' · From '+status.source:'');label.append(detail);row.append(check,label);$('cleanupList').append(row)}let pager=$('cleanupPager');if(!pager){pager=document.createElement('div');pager.id='cleanupPager';$('cleanupList').after(pager)}pager.replaceChildren();let prev=document.createElement('button'),next=document.createElement('button'),label=document.createElement('span');prev.id='cleanupPrev';next.id='cleanupNext';prev.textContent='Previous';next.textContent='Next';prev.disabled=cleanupPage===0;next.disabled=(cleanupPage+1)*100>=items.length;prev.onclick=()=>{cleanupPage--;renderCleanup()};next.onclick=()=>{cleanupPage++;renderCleanup()};label.textContent=' Page '+(cleanupPage+1)+' of '+Math.max(1,Math.ceil(items.length/100))+' · '+items.length+' matching items ';pager.append(prev,label,next);updateCleanupCount()}
$('manageBacklog').onclick=()=>{endBurst();cleanupPage=0;cleanupCache=null;cleanupSelection.clear();$('cleanupFilter').value='';$('cleanupError').textContent='';renderCleanup();$('cleanupDialog').showModal()};$('closeCleanup').onclick=()=>$('cleanupDialog').close();$('cleanupFilter').oninput=()=>{clearTimeout(cleanupTimer);cleanupTimer=setTimeout(()=>{cleanupPage=0;renderCleanup()},150)};$('selectAllBacklog').textContent='Select all matching';$('selectAllBacklog').onclick=()=>{cleanupItems().forEach(t=>cleanupSelection.add(t.id));renderCleanup()};$('selectNoneBacklog').onclick=()=>{cleanupSelection.clear();renderCleanup()};$('removeOldCarried').onclick=()=>{let age=+$('cleanupAge').value;if(!Number.isInteger(age)||age<0||age>36500){$('cleanupError').textContent='Choose 0–36500 days.';return}cleanupSelection=new Set(C.oldCarriedItems(data,age));$('cleanupFilter').value='';$('cleanupError').textContent='Only verified untouched, unfinished, never-scheduled items are preselected. Edited, completed, scheduled or unverified items need manual selection.';renderCleanup()};
async function removeBacklogBatch(ids){ids=ids.filter(id=>data.backlog[id]);if(!ids.length){$('cleanupError').textContent='No matching items.';return}if(!confirm('Remove '+ids.length+' backlog items? Calendar blocks stay. You can Undo this batch.'))return;try{await flush();let backup=await window.desktop.checkpoint();if(backup.error)throw Error(backup.error);mutate(()=>C.removeBacklog(data,ids));cleanupSelection.clear();$('cleanupError').textContent=ids.length+' items removed. Use Undo to restore this batch.';renderCleanup()}catch(e){$('cleanupError').textContent='Nothing removed: '+e.message}}
$('removeSelectedBacklog').onclick=()=>removeBacklogBatch([...cleanupSelection]);$('clearCompleted').onclick=()=>removeBacklogBatch(Object.values(data.backlog).filter(t=>t.done).map(t=>t.id));
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initialize,{once:true});else queueMicrotask(initialize);

function legacyEntries(){let rows=[];for(let [date,day]of Object.entries(data.days))for(let kind of ['legacyActual','legacyQuarantine'])for(let [index,value]of (day[kind]||[]).entries())rows.push({date,kind,index,record:kind==='legacyQuarantine'?value.record:value,reason:kind==='legacyQuarantine'?value.reason:'Legacy actual-time entry'});return rows}
function updateLegacyReview(){let n=legacyEntries().length;$('legacyReview').hidden=!n;$('legacyReview').textContent='Review '+n+' legacy entr'+(n===1?'y':'ies')}
function renderLegacy(){let rows=legacyEntries();$('legacyRows').replaceChildren();for(let item of rows){let row=document.createElement('div'),text=document.createElement('p'),convert=document.createElement('button'),remove=document.createElement('button');text.style.whiteSpace='pre-wrap';text.textContent=item.date+' · '+item.reason+'\n'+JSON.stringify(item.record,null,2);convert.textContent='Convert to calendar block';convert.dataset.action='convert';convert.onclick=()=>{let b=item.record||{},cat=Object.hasOwn(data.categories,b.cat)?b.cat:activeTasks()[0];$('legacyDialog').close();openEditor(item.date,{cat,details:typeof b.details==='string'?b.details:typeof b.title==='string'?b.title:'Legacy entry',notes:typeof b.notes==='string'?b.notes:JSON.stringify(b),start:C.timing(b)?b.start:data.start*60,end:C.timing(b)?b.end:data.start*60+30});legacySource=item;};remove.textContent='Remove';remove.dataset.action='remove';remove.onclick=()=>{if(!confirm('Remove this preserved legacy entry? You can Undo this.'))return;mutate(()=>data.days[item.date][item.kind].splice(item.index,1));renderLegacy()};row.append(text,convert,remove);$('legacyRows').append(row)}if(!rows.length)$('legacyRows').textContent='No legacy entries remain.'}
$('legacyReview').onclick=()=>{endBurst();renderLegacy();$('legacyDialog').showModal()};$('closeLegacy').onclick=()=>$('legacyDialog').close();

async function showHolidayUpgradeNotice(){if(!data.holidayMigrationSeriesIds?.some(id=>data.recurrences.some(r=>r.id===id&&r.skipDaysOff)))return;try{let status=await window.desktop.holidayNotice?.(false);$('holidayUpgradeNotice').hidden=!!status?.acknowledged}catch{$('holidayUpgradeNotice').hidden=false}}
$('dismissHolidayNotice').onclick=async()=>{try{let status=await window.desktop.holidayNotice?.(true);if(status?.error)throw Error(status.error);$('holidayUpgradeNotice').hidden=true}catch(e){notify('Could not remember this notice: '+e.message)}};$('reviewHolidaySettings').onclick=()=>$('recurringList').click();
